<?php
// تیکت‌های داخلی: کارمند و فروشنده باز می‌کنند؛ پشتیبان (tickets.manage) پاسخ می‌دهد و یادداشتِ داخلی می‌گذارد
$id = req_int('id');
if ($id) { $t = ticket_get($id);
    echo ui_card('تیکتِ ' . $t['no'] . ' — ' . $t['subject'], '<p class="muted">' . h($t['dept']) . ' · ' . h($t['opener']) . ' · ' . ui_badge(ticket_statuses()[$t['status']] ?? $t['status']) . ' · ' . jdate($t['created_at'], true) . '</p>'
        . implode('', array_map(fn($m) => '<div class="tmsg' . ($m['internal'] ? ' internal' : '') . ((int)$m['user_id'] === (int)$t['opener_id'] ? ' mine' : '') . '"><b>' . h($m['name']) . '</b> <small>' . jdate($m['created_at'], true) . ($m['internal'] ? ' — یادداشتِ داخلی' : '') . '</small><div>' . nl2br(h($m['body'])) . '</div>' . ($m['file'] ? '<a target="_blank" href="' . h(page_url('tickets', ['file' => $m['id']])) . '">📎 پیوست</a>' : '') . '</div>', ticket_messages($id)))
        . ($t['status'] !== 'closed' || can('tickets.manage') ? ui_form('ticket_reply', ['body' => ['پاسخ', 'textarea', 1]] + (can('tickets.manage') && (int)$t['opener_id'] !== (int)current_user()['id'] ? ['internal' => ['یادداشتِ داخلی (بازکنندهٔ تیکت نمی‌بیند)', 'check']] : []), [], ['hidden' => ['id' => $id], 'multipart' => 1, 'submit' => 'فرستادن', 'extra' => '<label class="field"><span>پیوست (تصویر/PDF)</span><input type="file" name="file" accept="image/*,application/pdf"></label>']) : '')
        . ($t['status'] !== 'closed' ? '<div class="actions">' . ui_btn_api('بستنِ تیکت', 'ticket_close', ['id' => $id], ['class' => 'sm', 'confirm' => 'بسته شود؟']) . '</div>' : ''));
    return; }
$st = isset(ticket_statuses()[$_GET['tab'] ?? '']) ? $_GET['tab'] : '';
echo ui_tabs(['' => 'باز'] + ticket_statuses(), $st, 'tickets');
echo '<div class="cols">' . ui_card('تیکت‌ها' . (can('tickets.manage') ? ' (همه)' : ' (من)'), ui_table(['no' => ['شماره', 'code'], 'subject' => 'موضوع', 'dept' => 'بخش', 'opener' => 'بازکننده', 'priority' => ['اولویت', fn($r) => ['high' => ui_badge('فوری', 'err'), 'normal' => 'عادی', 'low' => 'کم'][$r['priority']] ?? ''], 'status' => ['وضعیت', fn($r) => ui_badge(ticket_statuses()[$r['status']] ?? $r['status'], $r['status'] === 'pending' ? 'warn' : '')], 'updated_at' => ['به‌روز', 'datetime']], tickets_list($st), ['href' => fn($r) => page_url('tickets', ['id' => $r['id']]), 'empty' => 'تیکتی نیست.']))
    . ui_card('تیکتِ تازه', ui_form('ticket_open', ['subject' => ['موضوع', 'text', 1], 'dept' => ['بخش', 'select', 1, array_combine(ticket_depts(), ticket_depts())], 'priority' => ['اولویت', 'select', 1, ['normal' => 'عادی', 'high' => 'فوری', 'low' => 'کم']], 'body' => ['متن', 'textarea', 1]], [], ['multipart' => 1, 'then' => 'reload', 'extra' => '<label class="field"><span>پیوست (تصویر/PDF)</span><input type="file" name="file" accept="image/*,application/pdf"></label>'])) . '</div>';
